/* The AMBE+2 3600x2450 tables (ambe_tables.c, generated by py/gen_c_tables.py from mbelib's). */
#ifndef AMBE_TABLES_H
#define AMBE_TABLES_H

/* The tables of the hot loops (py/gen_c_tables.py IN_RAM): the firmware puts them into RAM with the vocoder's code
   (-DAMBE_RAM_DATA=__attribute__((section(".vocoder_rodata"))), ckcpu.ld) */
#ifndef AMBE_RAM_DATA
#define AMBE_RAM_DATA
#endif

extern const float AmbeW0table[120];
extern const int AmbeLtable[120];
extern const signed char AmbeVuv[32][8];
extern const int AmbeLmprbl[57][4];
extern const float AmbeDg[32];
extern const float AmbePRBA24[512][3];
extern const float AmbePRBA58[128][4];
extern const float AmbeHOCb5[32][4];
extern const float AmbeHOCb6[16][4];
extern const float AmbeHOCb7[16][4];
extern const float AmbeHOCb8[8][4];
extern const float Ws[321];
/* fixed point */
extern const short AmbeCosQ12[1025];      /* cos(2 pi i / 4096) x 4096, a quarter of the circle (cos_q12()) */
extern const short AmbeWsQ15[321];        /* Ws x 32768 (32767 at most) */
extern const short AmbeSqrtWsQ15[321];
extern const int AmbePhaseDispQ32[58];    /* the decoder's phase offsets, 2^32 = 2 pi */
extern const short AmbeDgQ12[32];         /* the codebooks x 4096 */
extern const short AmbePRBA24Q12[512][3];
extern const short AmbePRBA58Q12[128][4];
extern const short AmbeHOCb5Q12[32][4];
extern const short AmbeHOCb6Q12[16][4];
extern const short AmbeHOCb7Q12[16][4];
extern const short AmbeHOCb8Q12[8][4];
extern const short AmbeLog2Q12[257];      /* log2(1 + i / 256) x 4096 */
extern const unsigned short AmbeExp2Q15[257]; /* 2^(i / 256) x 32768 */
/* the integer encoder */
extern const short AmbeCos2048Q15[513];   /* cos(2 pi i / 2048) x 32768 (32767 at most), a quarter (cos2048_q15()) */
extern const short AmbeHammingQ15[256];   /* the analysis window */
extern const short AmbeWi2Q15[301];       /* the pitch window w_I^2, / its peak */
extern const short AmbeLpfQ15[21];        /* the 1 kHz low-pass of the pitch */
extern const short AmbeWinTQ12[2049];     /* the analysis window's transform, real, 32 a bin, / its peak */
extern const int AmbeW0BinsQ16[120];      /* f0 of b0 in 1024-point bins, Q16 */
extern const int AmbeLogPQ16[217];        /* ln P of the pitch grid P = 20 + i / 2 */
extern const short AmbePmQ14[217];        /* P max(w_I^2) */
extern const short AmbeInvDQ12[217];      /* 1 / (1 - P sum(w_I^4)) */
extern const unsigned char AmbePLo[217];  /* the grid indices within -20 % .. +20 % of each P */
extern const unsigned char AmbePHi[217];
extern const unsigned int AmbeGolayErr[2048]; /* Golay(23,12) syndrome -> error pattern of weight <= 3 */

#endif
